import{z as B,x as p,o as E,c as A,q as l,j as s,D as e,d as t,s as n,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"交替相移","description":"","frontmatter":{"title":"交替相移","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/alt-psm.md","filePath":"litho/alt-psm.md","lastUpdated":1791063341000}'),m={name:"litho/alt-psm.md"};function d(h,a,c,f,C,D){const r=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=l('<h1 id="交替相移" tabindex="-1">交替相移 <a class="header-anchor" href="#交替相移" aria-label="Permalink to &quot;交替相移&quot;">​</a></h1><div class="epigraph"><p>相邻开口做成 $0$ 与 $\\pi$，暗线靠相消过零，而不是靠衰减膜漏过百分之几的背景光。这是 Levenson 的强相移，不是上一课的 MoSi 合同。</p><footer>—— 据 Levenson, Viswanathan, Simpson 的相移掩模，以及随后交替型（alt-PSM）与 trim 流程的量产表述</footer></div><p><a href="/litho/binary-attpsm">上一课</a>把量产透射版钉成二元铬与衰减相移两类，并允许 Kirchhoff 薄屏 \\(t(x,y)\\)。缺口是强交替：\\(0/\\pi\\) 相邻分配、相位冲突、以及常常需要的第二张 trim。衰减型的透过率百分比不要再写一遍。亚分辨辅助杆留给<a href="/litho/sraf-assist">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>衰减型压低零级、一次曝光、可走标准 OPC，所以成为接触孔和许多 DUV 层的默认。密线栅若还要更黑的暗区、更宽的焦深，衰减的背景光不够：需要相邻开口相位差约 \\(180^\\circ\\)，让中线电场强制过零。这就是交替相移（alt-PSM、Levenson）。</p><p>缺口因此是「何时离开 att 合同、改走 0/π 染色」，而不是重讲相消干涉的第一性原理。<a href="/litho/phase-shift-mask">相移掩模</a>已经给过家族定义；本课只补交替型作为一层工艺的约束。</p><h3 id="相位是-2-染色" tabindex="-1">相位是 2-染色 <a class="header-anchor" href="#相位是-2-染色" aria-label="Permalink to &quot;相位是 2-染色&quot;">​</a></h3><p>给每一条目标暗线的两侧开口涂上相反相位，等价于对开口做图染色。二维连通一旦出现奇数环，无法 2-染色，就是相位冲突。设计规则要么禁止这种拓扑，要么接受 trim：第二次二进制曝光切掉不该留下的相位边。无铬相移（CPL 等）把透过区铺得更满，冲突与 OPC 更重，量产渗透仍不如 att。</p><p><span class="marginnote">2-染色可以类比国际象棋棋盘：相邻格必须异色。棋盘能染到底，是因为任何一圈格子绕回起点都撞不到『必须变色』；只要出现奇数长的环就染不下去——这就是相位冲突的图论本义。</span></p><p><span class="marginnote">相位边本身就是一条暗线。想要的栅极处这是特性；逻辑拐角处是缺陷。不要把「用了 PSM」理解成版图可以任意二维连通。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>石英台阶或等效膜系使光程差约 \\(\\lambda/2\\)。相邻开口 \\(0/\\pi\\) 交替，铬可以很窄。典型流程：alt 掩模印出密线 → 二进制 trim 去掉多余相位边 → 转印。这已是两次光刻，套刻与产能要计入，和 LELE 的「两张分解掩模」不是同一件事：trim 删的是相位残影，不是把节距染色成两套线。</p><p><span class="marginnote">λ/2 光程差对应 180° 相位差：对 193 nm 的光就是约 96.5 nm 的光程差；换算成石英台阶的物理深度，还要除以石英与空气的折射率差，量级缩到几十纳米。</span></p><p>照明：交替型对部分相干与对准更挑剔，不能照搬 att + 环带的孔食谱。OPC 必须带相位通道；把上一课的 att 模型套上来，会在相位边造出假图形。</p><h3 id="与衰减型对照" tabindex="-1">与衰减型对照 <a class="header-anchor" href="#与衰减型对照" aria-label="Permalink to &quot;与衰减型对照&quot;">​</a></h3><p>Att-PSM：图形仍由石英开口定义，暗区是弱透过 + \\(180^\\circ\\)。Alt-PSM：暗线由干涉保证，分辨率潜力更大，掩模相位缺陷几乎不可按铬缺陷那样补镀。检测必须对相位通道敏感。本课不把掩模厂良率写成节点良率。</p>',16)),(E(),s(o,null,{default:e(()=>[n(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20ATT%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%20att-PSM%22%5D%20--%3E%20ONCE%5B%22%E4%B8%80%E6%AC%A1%E6%9B%9D%E5%85%89%20%E5%BC%B1%E7%9B%B8%E7%A7%BB%22%5D%0A%20%20ALT%5B%220%2F%CF%80%20%E4%BA%A4%E6%9B%BF%22%5D%20--%3E%20ZERO%5B%22%E6%9A%97%E7%BA%BF%E5%BC%BA%E5%88%B6%E8%BF%87%E9%9B%B6%22%5D%0A%20%20ALT%20--%3E%20COL%5B%22%E5%BC%80%E5%8F%A3%202-%E6%9F%93%E8%89%B2%22%5D%0A%20%20COL%20--%3E%20TRIM%5B%22%E7%9B%B8%E4%BD%8D%E5%86%B2%E7%AA%81%E5%88%99%20trim%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[t("物体透过率 \\(t(x)=A(x)e^{i\\phi(x)}\\)，相邻周期的傅里叶零级互相抵消，能量进更高衍射级。离焦时选定级的相位关系仍能维持过零，故 DOF 往往优于二元密线。这与 "),i("a",{href:"/litho/off-axis-illumination"},"OAI"),t(" 正交：OAI 选哪些级进瞳，交替相移改级的相位与零级强度；二者可叠加，但强偶极 + 二进制有时已经够一维层，不一定值得上 alt。")],-1)),(E(),s(o,null,{default:e(()=>[n(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E4%BA%8C%E7%BB%B4%E5%BC%80%E5%8F%A3%E8%BF%9E%E9%80%9A%E5%9B%BE%22%5D%20--%3E%20Q%7B%22%E8%83%BD%202-%E6%9F%93%E8%89%B2%3F%22%7D%0A%20%20Q%20--%3E%7C%E8%83%BD%7C%20OK%5B%220%2F%CF%80%20%E7%9B%B8%E9%82%BB%E5%88%86%E9%85%8D%E6%88%90%E7%AB%8B%22%5D%0A%20%20Q%20--%3E%7C%E6%9C%89%E5%A5%87%E6%95%B0%E7%8E%AF%7C%20CON%5B%22%E7%9B%B8%E4%BD%8D%E5%86%B2%E7%AA%81%22%5D%0A%20%20CON%20--%3E%20FIX%5B%22%E6%94%B9%E8%AE%BE%E8%AE%A1%E6%8B%93%E6%89%91%20%E6%88%96%20trim%22%5D%0A%20%20FIX%20--%3E%20TR2%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%20trim%20%E6%9B%9D%E5%85%89%22%5D%0A%20%20TR2%20--%3E%20OVL%5B%22%E5%90%8C%E5%B1%82%E4%BA%8C%E6%AC%A1%E6%9B%9D%E5%85%89%E5%A5%97%E5%88%BB%22%5D%0A%20%20OVL%20--%3E%20RES%5B%22%E6%AE%8B%E7%BA%BF%20%2F%20%E5%88%87%E8%BF%9B%E6%A0%85%E6%9E%81%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>Trim 的空中像是二进制，套刻误差会让该切的相位边留下残线、或不该切的地方切进栅极。因此 alt 的一阶代价不只是「多一张版」，而是同层二次曝光的 overlay。</p><p>上一课的 MEF 在交替型里会改形状：暗线由过零钉住，对铬宽度不那么敏感，但对台阶深度与相位误差极敏感。OPC 若仍用 att 的 \\(t(x,y)\\)，过零位置会系统偏。</p><p><span class="marginnote">常见误区：『相移一定更准』。相位边处处生成暗线——栅极处是特性，逻辑拐角处就是一条多余的黑线；alt-PSM 的版图自由度是拿拓扑限制和 trim 成本换的。</span></p><p><span class="marginnote">\\(180^\\circ\\) 为某一 \\(\\lambda\\) 与台阶深度而设计。ArF 交替版不能拿到 KrF 上当同一 alt-PSM。换波长必须换台阶或膜系。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>逻辑上强交替常常输给「att 或二元 + OAI + OPC」，或输给后来的多重图形：设计规则、trim、相位缺陷加在一起，比再降一点 \\(k_1\\) 更贵。存储器与规则栅极层更适合。本课不把 Levenson 1982 写成 7 nm 良率论文。</p><p>SRAF 可以画在 alt 版上，但辅助杆的相位归属会再制造冲突；下一课按孤立线窗口讲辅助杆，不在这里提前铺规则表。EUV 反射掩模不是石英 0/π 台阶，不要把本课流程抄过去。</p><p><span class="marginnote">无铬相移是家族变体，会议演示不等于晶圆厂默认下单。本课的量产对象仍是「有铬的 0/π 交替 ± trim」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交替相移用 0/π 相邻开口强制暗区过零，强于 att 的弱背景。</li><li>开口必须可 2-染色；奇数环要改设计或 trim。</li><li>Trim 是第二次光刻，套刻进入残线风险。</li><li>不重写二元 / att 合同；不替代 OAI。</li><li>孤立线辅助杆下一课。</li><li>出处：Levenson et al., IEEE 1982 相移掩模；Mack 对 alt-PSM 与 trim 的教科书表述。</li></ul>',10))])}const _=B(m,[["render",d]]);export{u as __pageData,_ as default};
